const milestones = $input.all().map(i => i.json);

// Group by org_name
const grouped = {};
for (const m of milestones) {
  const key = m.org_name;
  if (!grouped[key]) grouped[key] = { org_id: m.org_id, org_name: m.org_name, milestones: [] };
  grouped[key].milestones.push({
    milestone_id: m.id,
    program_name: m.program_name,
    nist_id: m.nist_id,
    due_date: m.current_milestone_date,
    responsible_org: m.responsible_org
  });
}

const summary = Object.values(grouped);
const total = milestones.length;

const logMessage = `POA&M reminder check: ${total} milestone(s) due within 7 days across ${summary.length} organization(s). Orgs: ${summary.map(g => g.org_name + ' (' + g.milestones.length + ')').join(', ')}`;

return [{
  json: {
    summary_json: JSON.stringify({
      run_date: new Date().toISOString(),
      total_milestones: total,
      orgs_affected: summary.length,
      detail: summary
    }),
    log_message: logMessage,
    total
  }
}];
